import React, { useEffect, useRef, useState } from 'react';
import './Works.css';
import axtrart from '../assets/axtrart.jpg';
import ptc     from '../assets/ptc.jpg';
import ptt     from '../assets/ptt.jpg';
import safe    from '../assets/safe.jpg';
import twpc    from '../assets/twpc.jpg';
import wash    from '../assets/wash02.jpg';

const projects = [
  { id:1, title:'AXTRART',        category:'IR System',         tags:['Content Page'],         img:axtrart, size:'wide'   },
  { id:2, title:'TMAN',         category:'IR System',         tags:['Full Website'],  img:tman,     size:'wide'   },
  { id:3, title:'PTC IR',         category:'IR System',         tags:['Full Website'],        img:ptc,     size:'normal' },
  { id:3, title:'PTC IR',         category:'IR System',         tags:['Full Website'],        img:ptc,     size:'normal' },
  { id:4, title:'SAFE Fertility', category:'Corporate Website', tags:['Only Corporate'],           img:safe,    size:'normal' },
  { id:5, title:'TWPC SD Journey',category:'Corporate Website', tags:['Full Website'],       img:twpc,    size:'tall'   },
  { id:6, title:'WashXpress',     category:'Corporate Website', tags:['HomePage'],           img:wash,    size:'wide'   },
];

const filters = ['All','IR System','Corporate Website'];

export default function Works() {
  const ref = useRef(null);
  const [active, setActive] = useState('All');
  const [hovered, setHovered] = useState(null);
  const filtered = active === 'All' ? projects : projects.filter(p => p.category === active);

  useEffect(() => {
    const obs = new IntersectionObserver(
      entries => entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); }),
      { threshold: 0.08 }
    );
    ref.current?.querySelectorAll('.reveal').forEach(el => obs.observe(el));
    return () => obs.disconnect();
  }, [active]);

  return (
    <section className="works section" id="works" ref={ref}>
      <div className="section-header reveal">
        <span className="section-tag">Portfolio</span>
        <h2 className="section-title">My <span>Works</span></h2>
        <p className="section-sub">Selected projects I've built and shipped</p>
      </div>

      <div className="works__filters reveal">
        {filters.map(f => (
          <button key={f} className={`wf-btn ${active===f?'active':''}`} onClick={() => setActive(f)}>
            {f}
          </button>
        ))}
      </div>

      <div className="works__masonry">
        {filtered.map((p, i) => (
          <div
            key={p.id}
            className={`wcard wcard--${p.size} reveal`}
            style={{'--delay':`${i*0.07}s`}}
            onMouseEnter={() => setHovered(p.id)}
            onMouseLeave={() => setHovered(null)}
          >
            <div className="wcard__img-wrap">
              <img src={p.img} alt={p.title} />
              <div className={`wcard__overlay ${hovered===p.id?'show':''}`}>
                <div className="wcard__ov-inner">
                  <div className="wcard__tags">
                    {p.tags.map(t => <span key={t} className="wtag">{t}</span>)}
                  </div>
                  <h3 className="wcard__ov-title">{p.title}</h3>
                  <span className="wcard__ov-cat">{p.category}</span>
                </div>
              </div>
            </div>
            <div className="wcard__foot">
              <span className="wcard__cat">{p.category}</span>
              <h3 className="wcard__title">{p.title}</h3>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
